/*
 * The base cache reader, on a fixture written by the test itself.
 *
 * The fixture is deliberately untidy -- escaped strings, a base with no coordinates, a base
 * with an empty mountpoint, an unknown field, whitespace and a trailing member -- because the
 * file this reads is generated by a script that will change, and a reader that only copes with
 * the exact bytes its author wrote is a reader waiting to fail on the first regeneration.
 */
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#include "vbs/vbs_basecache.h"
#include "vbs/vbs_basemeta.h"
#include "vbs/vbs_policy.h"

static int nfail;

static void check(int ok, const char *what) {
	printf("  %-66s %s\n", what, ok ? "ok" : "FAIL");
	if (!ok)
		nfail++;
}

static const char *FIXTURE =
"{\n"
"  \"version\": 1,\n"
"  \"generated\": \"2026-09-13T15:00:00Z\",\n"
"  \"note\": \"a field the reader has never heard of\",\n"
"  \"bases\": [\n"
"    {\"mp\": \"STA_M\", \"marker\": \"X00100EXA\", \"rec\": \"UBL-F9P\", \"ant\": \"BEIBT800S\",\n"
"     \"frame\": \"RGF93\", \"xyz\": [4582081.2, 55183.6, 4421736.6], \"gps_bands\": \"12\", \"live\": true},\n"
"    {\"mp\": \"VJ01\", \"marker\": \"B33200CAN\", \"rec\": \"SEPT MOSAIC-X5\", \"ant\": \"SEPCHOKE_B3E6 \\\"quoted\\\"\",\n"
"     \"frame\": \"ITRF2020\", \"xyz\": [1600000.0, -3700000.0, 4900000.0], \"gps_bands\": \"125\", \"live\": false},\n"
"    {\"mp\": \"NOCOORD\", \"rec\": \"UNICORE UM980\", \"xyz\": [0, 0, 0]},\n"
"    {\"mp\": \"\", \"rec\": \"UNICORE UM980\", \"xyz\": [4582000, 55000, 4421000]},\n"
"    {\"mp\": \"UMX\", \"marker\": \"X00200EXA\", \"rec\": \"UNICORE UM980\", \"frame\": \"RGF93\",\n"
"     \"xyz\": [4582000.0, 60000.0, 4421000.0], \"extra\": [1, 2, {\"deep\": null}]}\n"
"  ]\n"
"}\n";

int main(void) {
	char path[] = "/tmp/vbs_basecache_test_XXXXXX";
	int fd = mkstemp(path);
	FILE *fp;
	struct vbs_basecache bc;
	struct vbs_policy_base pb[8];
	int n, i;
	double h;

	printf("=== base cache ===\n");
	if (fd < 0) {
		printf("  cannot create fixture\n");
		return 1;
	}
	fp = fdopen(fd, "w");
	fputs(FIXTURE, fp);
	fclose(fp);

	n = vbs_basecache_load(path, &bc);
	check(n == 3, "three usable bases out of five records (no coords and no mountpoint dropped)");
	i = vbs_basecache_find(&bc, "STA_M");
	check(i >= 0 && !strcmp(bc.e[i].marker, "X00100EXA") && !strcmp(bc.e[i].frame, "RGF93"),
	    "STA_M: marker and frame read");
	check(i >= 0 && bc.e[i].family == VBS_FAM_F9P && bc.e[i].gps_bands == 2,
	    "STA_M: F9P family, two GPS bands");
	check(i >= 0 && fabs(bc.e[i].llh[0] * 180.0 / 3.14159265358979 - 44.15) < 0.5,
	    "STA_M: geodetic latitude derived (~44N)");
	i = vbs_basecache_find(&bc, "VJ01");
	check(i >= 0 && bc.e[i].family == VBS_FAM_MOSAIC && bc.e[i].gps_bands == 3 && !bc.e[i].live,
	    "VJ01: Mosaic, three bands, registry says not live");
	check(i >= 0 && strstr(bc.e[i].ant, "\"quoted\"") != NULL, "escaped quotes survive in a string");
	i = vbs_basecache_find(&bc, "UMX");
	check(i >= 0 && bc.e[i].gps_bands == 0 && bc.e[i].live, "UMX: bands unknown (0), live by default");
	check(vbs_basecache_find(&bc, "NOCOORD") < 0, "a base without coordinates is not loaded");
	check(!strcmp(bc.generated, "2026-09-13T15:00:00Z"), "generated stamp read");

	n = vbs_basecache_policy_view(&bc, 0, pb);
	check(n == 3 && pb[1].live == 0, "policy view uses the registry's live flag");
	bc.e[1].stream_ok = 1;
	n = vbs_basecache_policy_view(&bc, 1, pb);
	check(n == 3 && pb[1].live == 1 && pb[0].live == 0, "policy view uses stream state when asked");

	check(vbs_basecache_height_at(&bc, 44.15, 0.69, 120.0, &h) == 0 && h > -100.0 && h < 2000.0,
	    "height at a French position comes from the bases in reach");
	check(vbs_basecache_height_at(&bc, -30.0, 140.0, 120.0, &h) < 0,
	    "height in the middle of nowhere: no base in reach, refused");

	vbs_basecache_free(&bc);
	unlink(path);

	/*
	 * --coords: the reference document repositions the cache (D146). Four outcomes have to be
	 * distinguished, and tests/coords_cases.json carries one station for each, so the
	 * format is documented by the thing the test runs against rather than by a comment.
	 *
	 * The bound is the part worth testing hardest. The production document contains entries
	 * 160 and 215 km from the registry, and a mismatched mountpoint is indistinguishable from
	 * one, so an override past the bound must be refused rather than clamped or averaged.
	 */
	{
		struct vbs_basecache cc;
		double before[3], worst = -1.0;
		int nref = -1, applied, k;

		fp = fopen(path, "w");
		fputs("{\"bases\": [\n"
		      " {\"mp\":\"EX01\",\"marker\":\"X00100EXA\",\"rec\":\"SEPT MOSAIC-X5\","
		      "  \"xyz\":[4300000.0,100000.0,4700000.0],\"live\":true},\n"
		      " {\"mp\":\"EX02\",\"marker\":\"X00200EXA\",\"rec\":\"SEPT MOSAIC-X5\","
		      "  \"xyz\":[4300100.0,100100.0,4700100.0],\"live\":true},\n"
		      " {\"mp\":\"EX03\",\"marker\":\"X00300EXA\",\"rec\":\"SEPT MOSAIC-X5\","
		      "  \"xyz\":[4300200.0,100200.0,4700200.0],\"live\":true},\n"
		      " {\"mp\":\"EX04\",\"marker\":\"X00400EXA\",\"rec\":\"SEPT MOSAIC-X5\","
		      "  \"xyz\":[4300300.0,100300.0,4700300.0],\"live\":true}\n"
		      "]}\n", fp);
		fclose(fp);
		check(vbs_basecache_load(path, &cc) == 4, "four-base cache for the coords test");

		k = vbs_basecache_find(&cc, "EX03");
		memcpy(before, cc.e[k].xyz, sizeof before);

		applied = vbs_basecache_apply_coords(&cc, "tests/coords_cases.json",
		    5.0, &nref, &worst);
		check(applied == 2, "two of four bases repositioned");
		check(nref == 2, "two refused: one past the bound, one on quality");
		check(worst > 0.01 && worst < 0.1, "the worst applied shift is centimetre-scale");

		k = vbs_basecache_find(&cc, "EX01");
		check(fabs(cc.e[k].xyz[0] - 4300000.01) < 1e-6,
		    "EX01 took the new coordinate");
		check(!strcmp(cc.e[k].frame, "RGF93 v2b"),
		    "and its reference frame, which the registry never carried");

		k = vbs_basecache_find(&cc, "EX03");
		check(memcmp(cc.e[k].xyz, before, sizeof before) == 0,
		    "THE BOUND: a 100 km override is refused, NOT clamped and not averaged");

		k = vbs_basecache_find(&cc, "EX04");
		check(fabs(cc.e[k].xyz[0] - 4300300.0) < 1e-6,
		    "an EXPLORATORY_GLOBAL_BASELINE entry is refused on the file's own quality flag");

		check(vbs_basecache_apply_coords(&cc, "/nonexistent/coords.json", 5.0, NULL, NULL) < 0,
		    "a missing coords file is an error, not a silent no-op");
		vbs_basecache_free(&cc);
		unlink(path);
	}

	/*
	 * The coordinate rule (2026-10-02) and the horizontal bound. A base the document does not
	 * position -- absent, or refused -- is untrusted: invisible to the policy and to tile
	 * heights. A document entry differing from the registry only in HEIGHT is the registry's
	 * height being wrong (16 of the 17 production refusals were exactly that, by the local
	 * geoid) and is accepted; one differing HORIZONTALLY past the bound is a different place
	 * and is refused.
	 */
	{
		struct vbs_basecache cc;
		struct vbs_policy_base tpb[3];
		double llh[3] = {46.8 * D2R, 7.1 * D2R, 600.0}, xyz[3][3], doc[2][3], dr[3], pos[3], th;
		char cpath[] = "/tmp/vbs_basecache_cache_XXXXXX", dpath[] = "/tmp/vbs_basecache_doc_XXXXXX";
		int cfd = mkstemp(cpath), dfd = mkstemp(dpath), ii, kk, nun;
		FILE *f;

		/* H, M, A: 0, 2 and 4 km north of one point, all live in the registry */
		for (ii = 0; ii < 3; ii++) {
			pos[0] = llh[0] + (2.0 * ii) / 6371.0;
			pos[1] = llh[1];
			pos[2] = llh[2];
			pos2ecef(pos, xyz[ii]);
		}
		/* the document: H 47.07 m higher, nothing else; M 10 m east; A absent */
		ecef2pos(xyz[0], pos);
		enu2ecef(pos, (double[]){0.0, 0.0, 47.07}, dr);
		for (kk = 0; kk < 3; kk++)
			doc[0][kk] = xyz[0][kk] + dr[kk];
		ecef2pos(xyz[1], pos);
		enu2ecef(pos, (double[]){10.0, 0.0, 0.0}, dr);
		for (kk = 0; kk < 3; kk++)
			doc[1][kk] = xyz[1][kk] + dr[kk];

		f = fdopen(cfd, "w");
		fprintf(f, "{\"bases\": [\n");
		for (ii = 0; ii < 3; ii++)
			fprintf(f, " {\"mp\":\"%s\",\"marker\":\"X0%d000CHE\",\"rec\":\"SEPT MOSAIC-X5\","
			    "\"xyz\":[%.4f,%.4f,%.4f],\"live\":true}%s\n", (const char *[]){"H", "M", "A"}[ii],
			    ii, xyz[ii][0], xyz[ii][1], xyz[ii][2], ii < 2 ? "," : "");
		fprintf(f, "]}\n");
		fclose(f);
		f = fdopen(dfd, "w");
		fprintf(f, "{\"sources\": {\n");
		for (ii = 0; ii < 2; ii++)
			fprintf(f, " \"%s\": {\"mp\":\"%s\",\"x_m\":%.4f,\"y_m\":%.4f,\"z_m\":%.4f,"
			    "\"reference_frame\":\"CHTRS95\",\"calculation_quality\":\"PRELIMINARY_NOT_QUALIFIED\"}%s\n",
			    ii ? "M" : "H", ii ? "M" : "H", doc[ii][0], doc[ii][1], doc[ii][2], ii ? "" : ",");
		fprintf(f, "}}\n");
		fclose(f);

		check(vbs_basecache_load(cpath, &cc) == 3, "three-base cache for the trust test");
		check(vbs_basecache_apply_coords(&cc, dpath, 5.0, NULL, NULL) == 1,
		    "one base repositioned: the height-only correction");
		kk = vbs_basecache_find(&cc, "H");
		check(cc.e[kk].coord_from_ref && fabs(cc.e[kk].xyz[0] - doc[0][0]) < 1e-3,
		    "a 47 m HEIGHT difference is accepted: the registry height was wrong");
		kk = vbs_basecache_find(&cc, "M");
		check(!cc.e[kk].coord_from_ref && fabs(cc.e[kk].xyz[0] - xyz[1][0]) < 1e-3,	/* %.4f in the file */
		    "a 10 m HORIZONTAL difference is refused: a different place");

		nun = vbs_basecache_require_ref(&cc);
		check(nun == 2, "require_ref: the refused base and the absent one are untrusted");
		vbs_basecache_policy_view(&cc, 0, tpb);
		check(tpb[vbs_basecache_find(&cc, "H")].live && !tpb[vbs_basecache_find(&cc, "M")].live &&
		    !tpb[vbs_basecache_find(&cc, "A")].live,
		    "the policy sees only the trusted base, though all three are live");
		check(vbs_basecache_height_at(&cc, 46.8, 7.1, 10.0, &th) == 0 && fabs(th - 647.07) < 0.01,
		    "tile height comes from the trusted base alone (its corrected 647.07 m)");
		vbs_basecache_free(&cc);
		unlink(cpath);
		unlink(dpath);
	}

	/*
	 * SIGHUP reload: vbsd merges a freshly read cache into the live one. It used to copy the
	 * registry coordinates straight over the --coords repositioning, never refresh the firmware
	 * (so an upgraded UM980 stayed refused until a restart, against the fw field's own
	 * contract), and leave coord_from_ref claiming reference coordinates that were gone.
	 */
	{
		static const char *before_json =
		    "{\"generated\": \"t0\", \"bases\": [\n"
		    " {\"mp\":\"EX01\",\"marker\":\"X00100EXA\",\"rec\":\"SEPT MOSAIC-X5\",\"fw\":\"Build11833\","
		    "  \"xyz\":[4300000.0,100000.0,4700000.0],\"live\":true},\n"
		    " {\"mp\":\"EX02\",\"marker\":\"X00200EXA\",\"rec\":\"SEPT MOSAIC-X5\","
		    "  \"xyz\":[4300100.0,100100.0,4700100.0],\"live\":true},\n"
		    " {\"mp\":\"EX03\",\"marker\":\"X00300EXA\",\"rec\":\"SEPT MOSAIC-X5\","
		    "  \"xyz\":[4300200.0,100200.0,4700200.0],\"live\":true}\n"
		    "]}\n";
		static const char *after_json =
		    "{\"generated\": \"t1\", \"bases\": [\n"
		    " {\"mp\":\"EX01\",\"marker\":\"X00100EXA\",\"rec\":\"SEPT MOSAIC-X5\",\"fw\":\"Build17548\","
		    "  \"xyz\":[4300000.0,100000.0,4700000.0],\"live\":true},\n"
		    " {\"mp\":\"EX02\",\"marker\":\"X00200EXA\",\"rec\":\"SEPT MOSAIC-X5\","
		    "  \"xyz\":[4300100.0,100100.0,4700100.0],\"live\":true},\n"
		    " {\"mp\":\"EX05\",\"marker\":\"X00500EXA\",\"rec\":\"SEPT MOSAIC-X5\","
		    "  \"xyz\":[4300400.0,100400.0,4700400.0],\"live\":true}\n"
		    "]}\n";
		const char *coords = "tests/coords_cases.json";
		struct vbs_basecache live, fresh;
		int up = -1, ad = -1, go = -1, k1, k;
		double ref1[3];

		fp = fopen(path, "w"); fputs(before_json, fp); fclose(fp);
		vbs_basecache_load(path, &live);
		vbs_basecache_apply_coords(&live, coords, 5.0, NULL, NULL);
		k1 = vbs_basecache_find(&live, "EX01");
		memcpy(ref1, live.e[k1].xyz, sizeof ref1);
		check(live.e[k1].coord_from_ref && fabs(ref1[0] - 4300000.01) < 1e-6,
		    "merge fixture: EX01 repositioned at startup");

		fp = fopen(path, "w"); fputs(after_json, fp); fclose(fp);
		vbs_basecache_load(path, &fresh);
		vbs_basecache_apply_coords(&fresh, coords, 5.0, NULL, NULL);
		check(vbs_basecache_merge(&live, &fresh, &up, &ad, &go) == 0, "merge succeeds");
		check(vbs_basecache_find(&live, "EX01") == k1, "indices do not move");
		check(!strcmp(live.e[k1].fw, "Build17548"), "a firmware upgrade is seen on reload");
		check(memcmp(live.e[k1].xyz, ref1, sizeof ref1) == 0 && live.e[k1].coord_from_ref &&
		    !strcmp(live.e[k1].frame, "RGF93 v2b"),
		    "the --coords repositioning survives the reload");
		check(up == 1, "exactly one entry counted updated: the firmware change");
		k = vbs_basecache_find(&live, "EX05");
		check(ad == 1 && k == 3 && live.n == 4 && live.e[k].live, "a new base is appended");
		k = vbs_basecache_find(&live, "EX03");
		check(go == 1 && !live.e[k].live, "a base gone from the file stays, not live");
		check(!strcmp(live.generated, "t1"), "the generation stamp follows the file");
		vbs_basecache_free(&fresh);

		/* the control: what the old reload did -- merge without re-applying --coords */
		vbs_basecache_load(path, &fresh);
		vbs_basecache_merge(&live, &fresh, NULL, NULL, NULL);
		check(fabs(live.e[k1].xyz[0] - 4300000.0) < 1e-6 && !live.e[k1].coord_from_ref,
		    "control: merging an un-repositioned file reverts EX01, as documented");
		vbs_basecache_free(&fresh);
		vbs_basecache_free(&live);
		unlink(path);
	}

	/* a string whose last byte is a backslash: the escape used to read past the end of the buffer (libFuzzer+ASan) */
	fp = fopen(path, "w");
	fputs("{\"bases\": [{\"mp\": \"A\\", fp);
	fclose(fp);
	check(vbs_basecache_load(path, &bc) < 0, "a string ending in a lone backslash is refused, not overrun");
	unlink(path);

	/* nesting: the recursive parser overflowed the stack on 200 000 nested brackets (segfault) */
	fp = fopen(path, "w");
	fputs("{\"bases\": ", fp);
	for (i = 0; i < 200000; i++)
		fputc('[', fp);
	for (i = 0; i < 200000; i++)
		fputc(']', fp);
	fputs("}", fp);
	fclose(fp);
	check(vbs_basecache_load(path, &bc) < 0, "200 000 nested brackets are refused, not a stack overflow");
	unlink(path);

	/* a well-formed file with no usable base: returns 0 and holds no allocation (callers free nothing on <= 0) */
	fp = fopen(path, "w");
	fputs("{\"bases\": [ {\"mp\": \"\", \"xyz\": [1,2,3]}, 7 ]}", fp);
	fclose(fp);
	check(vbs_basecache_load(path, &bc) == 0 && bc.e == NULL,
	    "no usable base: 0 returned and nothing left allocated");
	unlink(path);

	/* a broken file is refused with a message, not read as empty */
	fp = fopen(path, "w");
	fputs("{\"bases\": [ {\"mp\": \"X\", \"xyz\": [1,2,3] ", fp);
	fclose(fp);
	check(vbs_basecache_load(path, &bc) < 0, "truncated JSON is refused");
	unlink(path);

	printf("%s: %d failure(s)\n", nfail ? "FAILED" : "PASSED", nfail);
	return nfail != 0;
}
